// release-management/T46 to T53 and T61 to T63 (Cases of C8, carried unwired in the PLAN, wired by the DO, verify Envelope; verify-envelope-plan.md).
// Run by hand from the repository root; no suite or lane names this file until the DO makes it GREEN:
//
//   node --test engineering/release-management/04-test/verify-envelope.red.mjs
//
// The body is read with the Markdown parser, never a pattern over prose. Do not edit a Case to make it pass.
import assert from "node:assert/strict";
import { dirname, join, resolve } from "node:path";
import { test } from "node:test";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
// lazy, so each Case fails on its own while the module does not exist
const module_ = () => import(pathToFileURL(join(ROOT, "engineering", "release-management", "05-src", "envelope", "verify-envelope.mjs")).href);
const verify = async (facts) => (await module_()).verifyEnvelope(facts);

const BODY = "<!-- This pull request is a stable Change envelope. -->\n\n## Intent\n\nWhy this Change exists.\n\n## Design\n\nHow.\n\n## Verified by\n\nChecks.\n\n## Validated by\n\nReview.\n\n---\n_Generated by Claude Code_\n";
const facts = (over) => ({
  number: 7, kind: "change", title: "release-management/C8 PLAN: verify Envelope", body: BODY,
  capabilities: ["release-management", "engineering"], changeIds: { "release-management": ["C1", "C8"] },
  opened: "2026-11-11T08:00:00Z", activation: "2026-11-10T00:00:00Z", provenance: { kind: "lineage", registers: "base", activation: "base" }, ...over,
});
const lines = (v) => v.message.split("\n");

test("T46: the body has Intent, Design (optional), Verified by and Validated by as headings, once each, in order, found by parsing", async () => {
  assert.equal((await verify(facts())).kind, "pass");
  assert.equal((await verify(facts({ body: BODY.replace("## Design\n\nHow.\n\n", "") }))).kind, "pass", "Design is optional");
  for (const bad of [BODY.replace("## Verified by", "## Checked by"), BODY.replace("## Validated by\n\nReview.\n", ""), BODY.replace("## Intent", "## Intent\n\nA.\n\n## Intent")]) {
    const v = await verify(facts({ body: bad }));
    assert.equal(v.kind, "fail");
  }
  const swapped = BODY.replace("## Verified by\n\nChecks.\n\n## Validated by\n\nReview.\n", "## Validated by\n\nReview.\n\n## Verified by\n\nChecks.\n");
  assert.equal((await verify(facts({ body: swapped }))).kind, "fail", "out of order");
  const fenced = BODY.replace("## Verified by\n\nChecks.\n", "```\n## Verified by\n```\n");
  assert.equal((await verify(facts({ body: fenced }))).kind, "fail", "a heading inside a code block is not a heading");
});

test("T47: an Intent that holds only the template's comment is empty and fails", async () => {
  const empty = BODY.replace("Why this Change exists.", "<!-- What this Change must achieve. -->");
  const v = await verify(facts({ body: empty }));
  assert.equal(v.kind, "fail");
  assert.match(v.message, /Intent/);
});

test("T48: a Change title is <capability>/<C-ID> <PHASE>: <concern> with a known capability, a defined C id and a PHASE from PLAN, DO, ACT", async () => {
  for (const t of ["release-management/C8 DO: wire it", "release-management/C1 ACT: what we learned"]) assert.equal((await verify(facts({ title: t }))).kind, "pass", t);
  for (const t of ["Engineering: PLAN for something", "unknown/C8 PLAN: x", "release-management/C99 PLAN: x", "release-management/C8 RED: x", "release-management/C8 CHECK: x", "release-management/C8 PLAN:", "release-management/C8 PLAN x"])
    assert.equal((await verify(facts({ title: t }))).kind, "fail", t);
});

test("T49: whether a pull request is a Change, a promotion or a synchronization comes from the lineage, not from the title", async () => {
  const promo = { kind: "promotion", title: "PROMOTION kaal/x -> main: ship x" };
  const sync = { kind: "synchronization", title: "Synchronize kaal/x with main" };
  assert.equal((await verify(facts(promo))).kind, "pass");
  assert.equal((await verify(facts(sync))).kind, "pass");
  assert.equal((await verify(facts({ kind: "promotion", title: "release-management/C8 PLAN: x" }))).kind, "fail", "a Change form on a promotion");
  assert.equal((await verify(facts({ kind: "change", title: "PROMOTION kaal/x -> main: ship x" }))).kind, "fail", "a promotion form on a Change");
});

test("T50: pull requests opened before the activation boundary are not applicable, and the boundary is the trusted one, not the candidate's", async () => {
  const old = await verify(facts({ title: "Engineering: PLAN old", opened: "2026-11-09T08:00:00Z" }));
  assert.equal(old.kind, "not-applicable", "fall forward: nothing is blocked retroactively");
  const forged = await verify(facts({ title: "Engineering: PLAN new", opened: "2026-11-11T08:00:00Z", candidateActivation: "2099-01-01T00:00:00Z" }));
  assert.equal(forged.kind, "fail", "a boundary the candidate supplies is ignored");
});

test("T51: missing facts are no evidence, and a failure carries a recovery whose event re-runs the check", async () => {
  for (const over of [{ title: undefined }, { body: null }, { kind: undefined }]) assert.notEqual((await verify(facts(over))).kind, "pass");
  const v = await verify(facts({ title: "nonsense" }));
  const r = lines(v).filter((l) => l.startsWith("Recovery:"));
  assert.ok(r.length >= 1);
  for (const l of r) assert.match(l, /^Recovery: gh pr edit 7 --(title|body-file) .+ \(re-runs on: edited\)$/, l);
});

test("T52: the check is named exactly `verify Envelope`, the name track Work reads", async () => {
  assert.equal((await module_()).CHECK_NAME, "verify Envelope");
});

test("T53: the activation policy is trusted input: missing, malformed or non-UTC policy is refused and never read as a pass", async () => {
  const { loadPolicy } = await module_();
  assert.equal(loadPolicy('{"version":1,"cutoff":"2026-11-10T12:00:00Z"}').ok, true);
  for (const raw of [undefined, "", "not json", "{}", '{"version":1}', '{"version":2,"cutoff":"2026-11-10T12:00:00Z"}', '{"version":1,"cutoff":"2026-11-10T12:00:00+01:00"}', '{"version":1,"cutoff":"soon"}'])
    assert.equal(loadPolicy(raw).ok, false, String(raw));
});

test("T61: every fact is validated before any verdict, so a malformed fact never hides behind the activation cutoff", async () => {
  const old = { opened: "2026-11-09T08:00:00Z" };
  for (const over of [{ kind: undefined }, { kind: "release" }, { capabilities: "release-management" }, { capabilities: [1] }, { changeIds: null }, { changeIds: { "release-management": "C1" } }, { number: 0 }, { title: 7 }])
    for (const age of [{}, old]) assert.equal((await verify(facts({ ...age, ...over }))).kind, "fail", JSON.stringify({ ...age, ...over }));
  assert.equal((await verify(facts(old))).kind, "not-applicable", "well-formed facts before the cutoff stay not-applicable");
});

test("T62: timestamps are strict UTC: prose, a missing Z and an offset are refused for opened, the activation and the policy", async () => {
  for (const bad of ["yesterday", "Nov 10 2026 12:00:00Z", "2026-11-10", "2026-11-10T12:00:00+01:00", "2026-02-31T00:00:00Z"]) {
    assert.equal((await verify(facts({ opened: bad }))).kind, "fail", `opened ${bad}`);
    assert.equal((await verify(facts({ activation: bad }))).kind, "fail", `activation ${bad}`);
    assert.equal((await module_()).loadPolicy(JSON.stringify({ version: 1, cutoff: bad })).ok, false, `policy ${bad}`);
  }
});

test("T63: the trust contract is explicit: kind, registers and activation must be asserted as the lineage's and the base's, and the title parser is the one place", async () => {
  const m = await module_();
  for (const provenance of [undefined, {}, { kind: "title", registers: "base", activation: "base" }, { kind: "lineage", registers: "candidate", activation: "base" }, { kind: "lineage", registers: "base", activation: "candidate" }]) {
    const v = await verify(facts({ provenance }));
    assert.equal(v.kind, "fail", JSON.stringify(provenance));
    assert.match(v.message, /provenance/);
  }
  assert.deepEqual(m.parseChangeTitle("release-management/C8 DO: verify Envelope"), { capability: "release-management", id: "C8", phase: "DO", concern: "verify Envelope" });
  for (const t of ["release-management/C8 RED: x", "C8 DO: x", "release-management/C0 DO: x", 7, undefined]) assert.equal(m.parseChangeTitle(t), null, String(t));
});
